{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 청년 지원에서 교육비 도움과 진로 상담을 함께 알아볼 수 있는지",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울시 청년 기본 조례상 교육비 경감·여건 개선 방안 마련 의무(제11조제1항)와 취업애로 청년의 역량개발 대책 마련 노력 및 이용권 지급 가능성(제11조제2항)이 규정되어 있고, 서울광역청년센터는 ‘청년의 구직활동 지원을 위한 능력개발 및 진로모색 사업’을(제20조제2항제1호), 자치구별 서울청년센터는 ‘청년지원정보 집적·제공 및 분야별 종합상담 사업’을(제20조제3항제1호) 수행한다. 따라서 청년은 교육비와 진로 상담을 함께 알아볼 수 있는 근거가 조례에 마련되어 있으며, 실제 지원 여부·대상·절차는 예산 범위, 이용권 지급 조건, 센터 운영 등 세부 사항에 따라 달라질 수 있다.",
          "b_ids": "청년:제11조제1항, 청년:제11조제2항, 청년:제20조제2항제1호, 청년:제20조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
